62	   if (sec < 10) {var s = "0"+sec;}
63	   else {var s = sec;}
64	            var astanatime = ah+":"+m+":"+s;
65	            var minsktime = mh+":"+m+":"+s;
66	            $("#astanatime").html(astanatime);
67	            $("#minsktime").html(minsktime);
68	            sec = sec+1;
69	            if (sec >= 60) {
70	      sec = 0;
71	      min = min+1;
72	               if (min >= 60) {
73	                           min = 0;
